    schemeCitation: "Marking points quoted from the SEC marking scheme, Mathematics 2018 Ordinary Level — © State Examinations Commission.",
    id: "maths-2018-ol-p2-q1-b", topicId: "maths-1-2", conceptId: "p2-q1-b",
    section: "A", questionRef: "2018 OL Paper 2 Q1(b)",
    questionText: "A car distributor sells Ford cars and Renault cars. It has 30 cars for sale on a particular day; 18 are Ford cars and 12 are Renault cars. 7 of the Ford cars are red and 4 of the Renault cars are red. One of the 30 cars is chosen at random. What is the probability that the car chosen is a Ford car or a car which is not red?",
    tariffModel: {"kind":"questionTotal"}, totalMarks: 10,
    rows: [
    { id: "maths-2018-ol-p2-q1-b-solution-1", kind: "point", verbatim: "Model solution — (18 + 8)/30 = 26/30 = 13/15", marks: null, contextNote: "Each point is labelled with the part of the printed scheme it comes from. The original scheme reader provides the full solution, including diagrams, tables and graphs." },
    { id: "maths-2018-ol-p2-q1-b-solution-2", kind: "point", verbatim: "Model solution (alternative) — (30 − 4)/30 = 26/30 = 13/15", marks: null, contextNote: "Each point is labelled with the part of the printed scheme it comes from. The original scheme reader provides the full solution, including diagrams, tables and graphs." },
    { id: "maths-2018-ol-p2-q1-b-solution-3", kind: "point", verbatim: "Model solution (alternative) — (18 + (11 + 8) − 11)/30 = 26/30", marks: null, contextNote: "Each point is labelled with the part of the printed scheme it comes from. The original scheme reader provides the full solution, including diagrams, tables and graphs." },
    { id: "maths-2018-ol-p2-q1-b-solution-4", kind: "point", verbatim: "Low Partial Credit — Any relevant work towards creating at least one correct probability. (18 + 8, 30 – 4, 18 + 19 -11)", marks: null, contextNote: "Each point is labelled with the part of the printed scheme it comes from. The original scheme reader provides the full solution, including diagrams, tables and graphs." },
    { id: "maths-2018-ol-p2-q1-b-solution-5", kind: "point", verbatim: "High Partial Credit — Significant work towards answer.", marks: null, contextNote: "Each point is labelled with the part of the printed scheme it comes from. The original scheme reader provides the full solution, including diagrams, tables and graphs." },
    { id: "maths-2018-ol-p2-q1-b-solution-6", kind: "point", verbatim: "Full Credit — Correct answer without work.", marks: null, contextNote: "Each point is labelled with the part of the printed scheme it comes from. The original scheme reader provides the full solution, including diagrams, tables and graphs." },
    { id: "maths-2018-ol-p2-q1-b-solution-7", kind: "point", verbatim: "Zero Credit — Probability > 1, without work.", marks: null, contextNote: "Each point is labelled with the part of the printed scheme it comes from. The original scheme reader provides the full solution, including diagrams, tables and graphs." },
    ],
